#!/usr/bin/env node
// Greets the name given after the command, or the world when none is given.
// Usage: node greet.js [name...]

function greeting(args) {
  // Drop whitespace at the ends of each word, and leave out words left empty.
  const name = args.map((word) => word.trim()).filter((word) => word !== '').join(' ');
  return `Hello, ${name === '' ? 'world' : name}!`;
}

if (require.main === module) {
  console.log(greeting(process.argv.slice(2)));
}

module.exports = { greeting };
